VALUES (
  'lg', 'word_game', 'levels',
  'Initial Stage 1-2 Word Practice',
  $content${"title":"Ebigambo: Luganda Words","metadata":{"scope":"Fourteen single-word targets from the initial curriculum. Multi-word phrases are intentionally excluded because this mechanic builds one continuous word.","reviewStatus":"Draft text plus temporary bundled images and a placeholder audio cue. Native Luganda, early-years, cultural, accessibility, and final-media review are still required.","evidenceBoundary":"Completion records exposure or supported selection only; it does not prove speaking, independent recall, or mastery."},"levels":[{"id":"word-lg-greet-im-fine","order":1,"targetText":"Gyendi","question":"Build the Luganda word for: I am fine.","hint":"I am fine.","subHint":"The first letter is already shown.","firstLetter":"G","image":"black-kid.jpg"},{"id":"word-lg-courtesy-thanks","order":2,"targetText":"Weebale","question":"Build the Luganda word for: Thank you.","hint":"Thank you.","subHint":"The first letter is already shown.","firstLetter":"W","image":"child.png"},{"id":"word-lg-courtesy-forgive","order":3,"targetText":"Nsonyiwa","question":"Build the Luganda word for: Forgive me / excuse me.","hint":"Forgive me / excuse me.","subHint":"The first letter is already shown.","firstLetter":"N","image":"learning-beginner.jpg"},{"id":"word-lg-farewell-goodbye","order":4,"targetText":"Weeraba","question":"Build the Luganda word for: Goodbye.","hint":"Goodbye.","subHint":"The first letter is already shown.","firstLetter":"W","image":"river-kids.jpg"},{"id":"word-lg-body-head","order":5,"targetText":"Omutwe","question":"Build the Luganda word for: Head","hint":"Head","subHint":"The first letter is already shown.","firstLetter":"O","image":"child.png"},{"id":"word-lg-body-eyes","order":6,"targetText":"Amaaso","question":"Build the Luganda word for: Eyes","hint":"Eyes","subHint":"The first letter is already shown.","firstLetter":"A","image":"black-kid.jpg"},{"id":"word-lg-body-ears","order":7,"targetText":"Amatu","question":"Build the Luganda word for: Ears","hint":"Ears","subHint":"The first letter is already shown.","firstLetter":"A","image":"river-kids.jpg"},{"id":"word-lg-body-nose","order":8,"targetText":"Ennyindo","question":"Build the Luganda word for: Nose","hint":"Nose","subHint":"The first letter is already shown.","firstLetter":"E","image":"learning-beginner.jpg"},{"id":"word-lg-body-mouth","order":9,"targetText":"Akamwa","question":"Build the Luganda word for: Mouth","hint":"Mouth","subHint":"The first letter is already shown.","firstLetter":"A","image":"african-focus.png"},{"id":"word-lg-body-hand-arm","order":10,"targetText":"Omukono","question":"Build the Luganda word for: Hand / arm","hint":"Hand / arm","subHint":"The first letter is already shown.","firstLetter":"O","image":"african-logic.png"},{"id":"word-lg-body-leg","order":11,"targetText":"Okugulu","question":"Build the Luganda word for: Leg","hint":"Leg","subHint":"The first letter is already shown.","firstLetter":"O","image":"cards-matching.png"},{"id":"word-lg-body-foot","order":12,"targetText":"Ekigere","question":"Build the Luganda word for: Foot","hint":"Foot","subHint":"The first letter is already shown.","firstLetter":"E","image":"african-patterns.png"},{"id":"word-lg-feeling-tired","order":13,"targetText":"Nkooye","question":"Build the Luganda word for: I am tired.","hint":"I am tired.","subHint":"The first letter is already shown.","firstLetter":"N","image":"rain.jpg"},{"id":"word-lg-feeling-afraid","order":14,"targetText":"Ntya","question":"Build the Luganda word for: I am afraid.","hint":"I am afraid.","subHint":"The first letter is already shown.","firstLetter":"N","image":"culture.jpg"}],"progressRevision":4}$content$::jsonb,
