  $content${"title":"Okubala 1-5: Count from 1 to 5","metadata":{"scope":"Optional early counting reinforcement in three small steps; this is supplementary to the two Learning Hub stages.","reviewStatus":"Draft text plus temporary bundled images and a placeholder audio cue. Native Luganda, early-years, cultural, accessibility, and final-media review are still required."},"stages":[{"id":1,"order":1,"title":"Count 1-2","description":"Begin with one and two.","numbersRange":{"min":1,"max":2},"levels":2,"useBunches":false,"usesCurrency":false,"prompt":"How many can you see?"},{"id":2,"order":2,"title":"Count 1-3","description":"Add three in a second short step.","numbersRange":{"min":1,"max":3},"levels":3,"useBunches":false,"usesCurrency":false,"prompt":"How many can you see?"},{"id":3,"order":3,"title":"Count 1-5","description":"Review one through five.","numbersRange":{"min":1,"max":5},"levels":5,"useBunches":false,"usesCurrency":false,"prompt":"How many can you see?"}],"numbers":[{"number":1,"order":1,"targetText":"Emu"},{"number":2,"order":2,"targetText":"Bbiri"},{"number":3,"order":3,"targetText":"Ssatu"},{"number":4,"order":4,"targetText":"Nnya"},{"number":5,"order":5,"targetText":"Ttaano"}],"culturalItems":[{"id":"count-child","order":1,"name":"Children","image":"child.png"},{"id":"count-cards","order":2,"name":"Cards","image":"cards-matching.png"},{"id":"count-patterns","order":3,"name":"Patterns","image":"african-patterns.png"},{"id":"count-coins","order":4,"name":"Counters","image":"coin.png"},{"id":"count-numbers","order":5,"name":"Numbers","image":"numbers.png"}],"currency":[],"progressRevision":4}$content$::jsonb,
