  $content${"id":"morning-greeting","languageCode":"lg","title":"Ennamusa y'oku makya","summary":"Amina and Kato greet each other in four short pages.","metadata":{"status":"placeholder","notes":"Draft text plus temporary bundled images and a placeholder audio cue. Native Luganda, early-years, cultural, accessibility, and final-media review are still required.","sources":[{"label":"curriculum_guide/Baby_Steps_Lgeacy_Content_Lead.md"},{"label":"curriculum_guide/Baby_Steps_Content_Tracker_Stages_1_2.md"}]},"pages":[{"id":"lg-story-01-p01","text":"Ku makya, Amina alaba Kato.","translation":"In the morning, Amina sees Kato.","image":"culture.jpg","altText":"Temporary bundled illustration for: In the morning, Amina sees Kato."},{"id":"lg-story-01-p02","text":"Amina agamba nti, \"Oli otya, Kato?\"","translation":"Amina says, \"How are you, Kato?\"","image":"river-kids.jpg","altText":"Temporary bundled illustration for: Amina says, \"How are you, Kato?\""},{"id":"lg-story-01-p03","text":"Kato addamu nti, \"Gyendi. Weebale.\"","translation":"Kato replies, \"I am fine. Thank you.\"","image":"black-kid.jpg","altText":"Temporary bundled illustration for: Kato replies, \"I am fine. Thank you.\""},{"id":"lg-story-01-p04","text":"Bwe baba bagenda, bagamba nti, \"Weeraba.\"","translation":"When they are leaving, they say, \"Goodbye.\"","image":"river-kids.jpg","altText":"Temporary bundled illustration for: When they are leaving, they say, \"Goodbye.\""}],"questions":[{"id":"morning-greeting-q1","question":"Which words ask how a person is?","options":["Oli otya?","Gyendi.","Weeraba."],"correctAnswer":0},{"id":"morning-greeting-q2","question":"Which words say that you are fine?","options":["Nsonyiwa.","Gyendi.","Ggwe ani?"],"correctAnswer":1},{"id":"morning-greeting-q3","question":"Which word says goodbye?","options":["Weeraba.","Weebale.","Nze Amina."],"correctAnswer":0}],"progressRevision":4}$content$::jsonb,
