  $content${"id":"kato-and-the-ball","languageCode":"lg","title":"Kato n'omupiira","summary":"Kato plays with a ball and names body parts and feelings.","metadata":{"status":"placeholder","notes":"Draft text plus temporary bundled images and a placeholder audio cue. Native Luganda, early-years, cultural, accessibility, and final-media review are still required.","sources":[{"label":"curriculum_guide/Baby_Steps_Lgeacy_Content_Lead.md"},{"label":"curriculum_guide/Baby_Steps_Content_Tracker_Stages_1_2.md"}]},"pages":[{"id":"lg-story-02-p01","text":"Kato akwata omupiira n'emikono gye.","translation":"Kato holds the ball with his hands.","image":"child.png","altText":"Temporary bundled illustration for: Kato holds the ball with his hands."},{"id":"lg-story-02-p02","text":"Agukuba n'ekigere kye.","translation":"He kicks it with his foot.","image":"african-focus.png","altText":"Temporary bundled illustration for: He kicks it with his foot."},{"id":"lg-story-02-p03","text":"Omupiira gugenda wala. Kato munakuwavu.","translation":"The ball goes far away. Kato is sad.","image":"river-kids.jpg","altText":"Temporary bundled illustration for: The ball goes far away. Kato is sad."},{"id":"lg-story-02-p04","text":"Amina aguleeta. Kato musanyufu era agamba nti, \"Weebale.\"","translation":"Amina brings it back. Kato is happy and says, \"Thank you.\"","image":"black-kid.jpg","altText":"Temporary bundled illustration for: Amina brings it back. Kato is happy and says, \"Thank you.\""}],"questions":[{"id":"kato-ball-q1","question":"Which Luganda word means foot?","options":["Omukono","Okugulu","Ekigere"],"correctAnswer":2},{"id":"kato-ball-q2","question":"How do you say \"I am happy\" in Luganda?","options":["Nkooye.","Ndi musanyufu.","Ndi munakuwavu."],"correctAnswer":1},{"id":"kato-ball-q3","question":"How do you say \"I am tired\" in Luganda?","options":["Ntya.","Ndi musanyufu.","Nkooye."],"correctAnswer":2}],"progressRevision":4}$content$::jsonb,
